type Analysis struct {
	Inherited     InheritedRelation
	Algebra       SpectralAlgebraAudit
	ChargedLepton ChargedLeptonRootFunctional
	PMNS          PMNSSpectralProjectorAudit
	CKM           CKMSpectralCommutatorAudit
	Balance       BalanceFunctionalAudit
	Invariance    InvarianceAudit
	Availability  AvailabilityAudit
	Target        OperatorTarget
	Firewalls     FirewallAudit
	Final         FinalVerdict
	Truth         string
}

var cache struct {
	sync.Once
	a   Analysis
	err error
}

func BuildDefault() (Analysis, error) {
	cache.Once.Do(func() { cache.a, cache.err = Build() })
	return cache.a, cache.err
}

func Build() (Analysis, error) {
	g593, err := generation2orientationbalanceinvariantmatrixformaudit.BuildDefault()
	if err != nil {
		return Analysis{}, fmt.Errorf("build Gate593 predecessor: %w", err)
	}
	inherited := inheritGate593(g593)
	algebra := defineFlavorSpectralAlgebra()
	charged := defineChargedLeptonRootFunctional()
	pmns := definePMNSSpectralProjectors(inherited)
	ckm := defineCKMSpectralCommutator(inherited)
	balance := constructBFlav(inherited)
	invariance := auditInvarianceAndLabels()
	availability := auditAvailability()
	target := defineOperatorTarget()
	firewalls := auditFirewalls()
	final := compileFinal(invariance, availability, target)
	truth := "Gate 594 places the OrientationBalanceSeal inside one observed flavor spectral algebra A_flav=Alg(H_e,H_nu,H_u,H_d).  In that algebra epsilon(H_e) is a root-spectrum chamber functional, Tr(P_e P_3^nu) is the PMNS reactor projector overlap, and J(H_u,H_d) is the normalized CKM commutator area.  The resulting B_flav functional numerically reproduces the Gate 590/593 residual with sign B_flav=-Delta_590, but current ASHA has no native epsilon(H_e), PMNS projector, normalized CKM commutator-to-Koide-wall map, or theorem forcing B_flav=0."
	return Analysis{Inherited: inherited, Algebra: algebra, ChargedLepton: charged, PMNS: pmns, CKM: ckm, Balance: balance, Invariance: invariance, Availability: availability, Target: target, Firewalls: firewalls, Final: final, Truth: truth}, nil
}

func inheritGate593(g593 generation2orientationbalanceinvariantmatrixformaudit.Analysis) InheritedRelation {
	b := g593.Balance.LeftKappa - g593.Balance.RightProjectorMinusCKM
	return InheritedRelation{
		EpsilonObsRad:        g593.Inherited.EpsilonObsRad,
		KappaObs:             g593.Balance.LeftKappa,
		PMNSTrace:            g593.PMNS.TraceValue,
		PMNSQuarter:          g593.PMNS.ReactorQuarter,
		JCKM:                 g593.CKM.JCKM,
		RightHandCandidate:   g593.Balance.RightProjectorMinusCKM,
		Delta590:             g593.Balance.Residual,
		BFlavValue:           b,
		EpsilonPredictionRad: g593.Balance.EpsilonPredictionRad,
		EpsilonResidualRad:   g593.Balance.EpsilonResidualRad,
		ResidualInsideSigma:  g593.Balance.ResidualInsideSigma,
		Verdict:              StatusGate593Inherited,
	}
}

