func constructBFlav(in InheritedRelation) BalanceFunctionalAudit {
	return BalanceFunctionalAudit{
		Name:                "B_flav",
		Definition:          "B_flav(H_e,H_nu,H_u,H_d)=1-8*pi*epsilon(H_e)-(1/4)Tr(P_e P_3^nu)+J(H_u,H_d)",
		ExpandedDefinition:  "B_flav = kappa_e - sin^2(theta13)/4 + J_CKM = kappa_e - [(1/4)|U_e3|^2 - J_CKM]",
		LeftKappa:           in.KappaObs,
		ProjectorQuarter:    in.PMNSQuarter,
		JCKM:                in.JCKM,
		RightHandCandidate:  in.RightHandCandidate,
		BFlav:               in.BFlavValue,
		Delta590:            in.Delta590,
		SignConvention:      "Gate590 Delta_590 = [(1/4)|U_e3|^2 - J_CKM] - kappa_e; therefore B_flav = -Delta_590.",
		ResidualInsideSigma: in.ResidualInsideSigma,
		Verdict:             strings.Join([]string{StatusBalanceFunctionalConstructed, StatusNumericReproducesGate590593, StatusSpectralBalanceEnvironmental}, ";"),
	}
}

func auditInvarianceAndLabels() InvarianceAudit {
	items := []InvarianceItem{
		{Transformation: "common flavor-basis unitary conjugation", InvariantPart: "spectra of H_e, projector trace Tr(P_e P_3^nu), and normalized commutator J(H_u,H_d)", RequiredSeal: "all projectors transformed by the same basis change", Conclusion: "B_flav is basis-covariant/invariant once spectral labels are fixed.", Verdict: "PASS_BASIS_UNITARY_INVARIANCE_WITH_LABELS"},
		{Transformation: "field rephasings", InvariantPart: "projector overlap and Jarlskog invariant", RequiredSeal: "signed CKM orientation convention", Conclusion: "Magnitudes are rephasing invariant; signed J still needs orientation convention.", Verdict: "PASS_REPHASING_INVARIANCE_WITH_SIGN_SEAL"},
		{Transformation: "charged-lepton generation relabeling", InvariantPart: "unordered spectrum", RequiredSeal: "canonical chamber (e,mu,tau) and electron-zero wall", Conclusion: "epsilon(H_e) is not S3-invariant without chamber/wall labeling.", Verdict: "PASS_CHARGED_LEPTON_CHAMBER_LABEL_REQUIRED"},
		{Transformation: "neutrino mass ordering relabeling", InvariantPart: "projector trace after a mass projector is chosen", RequiredSeal: "third mass eigenstate P_3^nu and normal/inverted ordering convention", Conclusion: "The reactor overlap is label-dependent but projector-invariant once the label is sealed.", Verdict: "PASS_NEUTRINO_ORDERING_LABEL_REQUIRED"},
		{Transformation: "quark generation orientation reversal", InvariantPart: "|J| and normalized commutator magnitude", RequiredSeal: "signed CKM orientation convention", Conclusion: "The balance uses signed +J in B_flav; sign is a true orientation seal.", Verdict: "PASS_QUARK_ORIENTATION_SIGN_REQUIRED"},
	}
	return InvarianceAudit{Items: items, AllRequiredSealsNamed: true, BasisInvariantWithSeals: true, Verdict: StatusInvarianceAuditComplete}
}

