func compileFinal(inv InvarianceAudit, availability AvailabilityAudit, target OperatorTarget) FinalVerdict {
	native := availability.NativeBFlavZeroTheorem || target.NativePresent
	decision := "Gate 594 expresses all OrientationBalance terms inside the observed flavor spectral algebra A_flav=Alg(H_e,H_nu,H_u,H_d) and defines B_flav(H_e,H_nu,H_u,H_d)=1-8*pi*epsilon(H_e)-(1/4)Tr(P_e P_3^nu)+J(H_u,H_d).  It reproduces the Gate590/593 residual with sign B_flav=-Delta_590, but ASHA currently lacks the native root-spectrum epsilon functional, PMNS projector derivation, normalized CKM commutator-to-Koide-wall map, and theorem forcing B_flav=0.  B_flav=0 remains an environmental balance seal."
	return FinalVerdict{AllTermsInOneSpectralAlgebra: true, RequiredLabels: fmt.Sprintf("%d label/invariance seals", len(inv.Items)), NativeBFlavOperatorPresent: native, BFlavEnvironmental: !native, PromotionTheoremNeeded: target.NativeTheoremRequired, Decision: decision, Verdict: strings.Join([]string{StatusBalanceFunctionalConstructed, StatusNoBFlavZeroTheorem, StatusBFlavEnvironmental, StatusGate594Boundary}, ";")}
}

